node -e "
const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\n' + t.name + ':', cols.map(c => c.name + ' (' + c.type + ')').join(', '));
}
"

node -e "
const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync('/workspace/world.db');

// Order details
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = 'ORD-F15D7C'\").get();
console.log('=== ORDER ===');
console.log(JSON.stringify(order, null, 2));

// Order items
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-F15D7C'\").all();
console.log('\n=== ORDER ITEMS ===');
console.log(JSON.stringify(items, null, 2));

// Product details for each item
if (items.length > 0) {
  const productIds = [...new Set(items.map(i => i.product_id))];
  for (const pid of productIds) {
    const product = db.prepare('SELECT * FROM products WHERE product_id = ?').get(pid);
    console.log('\n=== PRODUCT: ' + pid + ' ===');
    console.log(JSON.stringify(product, null, 2));
  }
}

// Warranties
const warranties = db.prepare(\"SELECT * FROM warranties WHERE order_id = 'ORD-F15D7C'\").all();
console.log('\n=== WARRANTIES ===');
console.log(JSON.stringify(warranties, null, 2));

// Fulfillments
const fulfillments = db.prepare(\"SELECT * FROM order_fulfillments WHERE order_id = 'ORD-F15D7C'\").all();
console.log('\n=== FULFILLMENTS ===');
console.log(JSON.stringify(fulfillments, null, 2));

// Payments
const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = 'ORD-F15D7C'\").all();
console.log('\n=== PAYMENTS ===');
console.log(JSON.stringify(payments, null, 2));

// Customer info
if (order) {
  const customer = db.prepare('SELECT * FROM users WHERE user_id = ?').get(order.customer_id);
  console.log('\n=== CUSTOMER ===');
  console.log(JSON.stringify(customer, null, 2));
}
"
